        final body = read(actionPath);
        expect(
          body,
          contains('::error::'),
          reason:
              'an unresolvable version must fail the step with an ::error:: '
              'annotation — a silent empty version installs nothing and the '
              'build dies later in the very unretryable auto-install path '
