String dedupe(String text, String delta) {
  if (text.isEmpty || delta.isEmpty) return delta;
  if (delta.startsWith(text)) return delta.substring(text.length);
  var maxK = text.length < delta.length ? text.length : delta.length;
  if (maxK > 64) maxK = 64;
  for (var k = maxK; k >= 1; k--) {
    if (!text.endsWith(delta.substring(0, k))) continue;
    if (k == 1 && delta.length > 1 && delta.codeUnitAt(1) == delta.codeUnitAt(0)) {
      return delta;
    }
    return delta.substring(k);
  }
  return delta;
}
void main() {
  // Clean relay: new content legitimately starting with the tail char.
  print('"yes" + "sir"      -> "${'yes' + dedupe('yes', 'sir')}"   (want yessir)');
  print('"lorem ipsu" + "m dolor" -> "${'lorem ipsu' + dedupe('lorem ipsu', 'm dolor')}" (want lorem ipsum dolor)');
  // Stutter cases from the PR:
  print('"greeting." + "."  -> "${'greeting.' + dedupe('greeting.', '.')}" (want greeting.)');
  print('"hmm." + ".."      -> "${'hmm.' + dedupe('hmm.', '..')}" (want hmm...)');
}
